WITH history AS (SELECT DATE_TRUNC(`event_date`, DAY) AS period, COUNT(*) AS cnt FROM `fake_project.dataset.orders` WHERE `event_date` >= DATE('2026-05-01') - INTERVAL 28 DAY AND `event_date` < DATE('2026-05-01') GROUP BY period), medians AS (SELECT APPROX_QUANTILES(cnt, 100)[OFFSET(50)] AS median FROM history) SELECT (SELECT median FROM medians) AS median, APPROX_QUANTILES(ABS(cnt - (SELECT median FROM medians)), 100)[OFFSET(50)] AS mad, COUNT(*) AS n FROM history